def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, max(8.0, DAILY_SALARY * 0.35)))

    yesterday_bids = []
    threat_bid = 0.0
    cindy_like = False
    urgent_opp = False

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid')
        if b is not None:
            yesterday_bids.append(float(b))
            if float(b) > threat_bid:
                threat_bid = float(b)
            if float(b) >= 135.0:
                cindy_like = True
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp = True

    alive_count = len(alive)
    contest_ratio = float(WATER_REQ * (alive_count + 1)) / float(supply if supply > 0 else MIN_SUPPLY)
    tight_supply = supply <= 17
    medium_supply = supply <= 20
    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    base = DAILY_SALARY * 0.42

    if contest_ratio > 2.5:
        base = DAILY_SALARY * 1.55
    elif contest_ratio > 2.0:
        base = DAILY_SALARY * 1.2
    elif contest_ratio > 1.6:
        base = DAILY_SALARY * 0.92
    elif contest_ratio > 1.3:
        base = DAILY_SALARY * 0.72

    if tight_supply:
        base += 18.0
    elif medium_supply:
        base += 8.0
    else:
        base -= 6.0

    if cindy_like:
        if my_urgent or tight_supply:
            base = max(base, threat_bid + 3.0)
        else:
            base = min(base, DAILY_SALARY * 0.55)
    elif threat_bid > 0:
        if my_urgent:
            base = max(base, threat_bid + 2.0)
        elif threat_bid >= 100.0 and not tight_supply:
            base = min(base, DAILY_SALARY * 0.5)
        else:
            base = max(base, min(threat_bid + 1.5, DAILY_SALARY * 1.05))

    if urgent_opp and not my_urgent and not tight_supply:
        base *= 0.9

    if my_urgent:
        base = max(base, DAILY_SALARY * 1.0)
    if very_urgent:
        base = max(base, DAILY_SALARY * 1.35)

    days_left = max(1, 10 - int(day) + 1)
    reserve_floor = DAILY_SALARY * 0.25 * max(0, days_left - 1)
    affordable = max(0.0, budget - reserve_floor)

    if very_urgent:
        bid = min(budget, max(base, affordable, DAILY_SALARY * 1.1))
    else:
        if affordable <= 0:
            bid = min(budget, max(6.0, DAILY_SALARY * 0.25))
        else:
            bid = min(base, budget, max(12.0, affordable))
            bid = min(bid, budget)

    if hp >= 8 and no_water_days == 0 and supply >= 22 and threat_bid >= 120.0:
        bid = min(budget, DAILY_SALARY * 0.35)

    if day >= 8 and hp > 4:
        bid = min(budget, max(bid, DAILY_SALARY * 0.75 if tight_supply else DAILY_SALARY * 0.5))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, just bid to cover our need safely
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Use only yesterday's trace for immediate reaction
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    # Estimate pressure from yesterday bids
    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Urgency increases if we've already gone without water
    urgency = 1.0
    if no_water_days >= 2:
        urgency = 1.6
    elif no_water_days == 1:
        urgency = 1.25

    # If supply is high, we can bid less; if low, bid more
    # Normalize supply in [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        norm = 0.5
    norm = max(0.0, min(1.0, float(norm)))

    # Base bid target: moderate to beat low bidders but avoid Cindy's heavy spending
    # If yesterday pressure was very high, we avoid overmatching unless our HP is critical.
    base = DAILY_SALARY * (0.35 + 0.25 * (1.0 - norm))  # higher when supply is low

    if pressure >= DAILY_SALARY * 1.2:
        # Cindy-like behavior: only overbid if we are in danger
        if hp <= 2.0 or no_water_days >= 2:
            base = DAILY_SALARY * 0.85
        elif hp <= 4.0:
            base = DAILY_SALARY * 0.6
        else:
            base = DAILY_SALARY * 0.45
    elif pressure >= DAILY_SALARY * 0.7:
        # medium pressure
        if hp <= 3.0:
            base = DAILY_SALARY * 0.75
        else:
            base = DAILY_SALARY * 0.55

    # Apply urgency and HP
    if hp <= 1.0:
        base = DAILY_SALARY * 0.95
    elif hp <= 2.0:
        base = max(base, DAILY_SALARY * 0.8)
    elif hp <= 4.0:
        base = max(base, DAILY_SALARY * 0.6)

    bid = base * urgency

    # Never bid more than budget
    bid = min(bid, budget)

    # If budget is too low, bid whatever remains but keep it non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = 0.0

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = max(DAILY_SALARY * 0.8, highest_prev_bid + 10)
    else:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            bid = min(DAILY_SALARY * 0.85, highest_prev_bid + 5)
        else:
            bid = max(DAILY_SALARY * 0.55, highest_prev_bid + 5)

    if day_context['supply'] <= 17 and my_status['hp'] < 5:
        bid = max(bid, DAILY_SALARY * 0.8)

    if day_context['day'] == EPISODE_DAYS and my_status['hp'] <= 5:
        bid = my_status['budget']

    final_bid = min(my_status['budget'], bid)
    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    # Determine if we are desperate (no water for 2+ days or HP <=2)
    desperate = my_status['no_water_days'] >= 2 or hp <= 2
    # Extract yesterday's bids from opponents
    yesterday_bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest = max(yesterday_bids)
        # If opponents bid aggressively yesterday, adjust
        if highest >= 130:
            if desperate:
                bid = min(budget, DAILY_SALARY * 0.95)
            else:
                bid = min(budget, DAILY_SALARY * 0.3)
        else:
            # Less aggressive: outbid by small margin if needed
            target = max(highest + 1, DAILY_SALARY * 0.5)
            bid = min(budget, target)
    else:
        # No opponent trace (should not happen if all are new, but be safe)
        if desperate:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.55)
    # Adjust based on supply scarcity
    if supply < 18 and not desperate:
        bid = min(bid, DAILY_SALARY * 0.4)
    # Ensure bid is integer and within budget
    return int(min(bid, budget))
